NUL = -1

def _links(t):
    """vals[k], left[k], right[k] for the k-th real node in level order (-1 = no child)."""
    pos, c = [], 0
    for x in t:
        if x == NUL:
            pos.append(-1)
        else:
            pos.append(c)
            c += 1
    vals = [x for x in t if x != NUL]
    left, right = [-1] * c, [-1] * c
    for k in range(c):
        a = 2 * k + 1
        if a < len(t):
            left[k] = pos[a]
        if a + 1 < len(t):
            right[k] = pos[a + 1]
    return vals, left, right


def longestConsecutiveDown(tree):
    vals, left, right = _links(tree)
    n = len(vals)
    if n == 0:
        return 0
    ln = [1] * n
    best = 1
    for k in range(n):
        for c in (left[k], right[k]):
            if c != -1 and vals[c] == vals[k] + 1:
                ln[c] = ln[k] + 1
                if ln[c] > best:
                    best = ln[c]
    return best
